/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('Task.v');s=p.read_text();x=s.index('  - split_parts_wft.',s.index('Lemma algo_split_all'));y=s.index('  all: inversion H0',x)
s=s[:x]+'''  { split_parts_wft.
    split; [eapply AS_andl with (A2 := Y) | eapply AS_andr with (A1 := X)];
      eauto using AS_refl. }
  { split_parts_wft.
    split; [eapply AS_orl with (B2 := Y) | eapply AS_orr with (B1 := X)];
      eauto using AS_refl. }
  { split_parts_wft. split; auto using AS_top. }
  { split_parts_wft. split; auto using AS_bot. }
  { inversion S; subst; apply_split_ih; split; auto using AS_arrow. }
'''+s[y:];p.write_text(s)
PY
rocq compile -q -R . \"\" -R .rocq-deps/Metalib Metalib Task.v"

